// Where one champion appears: [[game id, role, extra]] in shelf order.
// role: playable | major | minor | main | supporting | cards. extra: TFT rows, 2XKO row, Wild Rift slug, or card count.
window.ATLAS_BEYOND.of=function(id){
  var B=window.ATLAS_BEYOND, out=[], LOR=window.ATLAS_LOR||{}, RB=window.ATLAS_RB||{};
  B.games.forEach(function(g){
    if(g.id==="tft"){ if(B.tft[id]) out.push([g.id,"playable",B.tft[id]]); return; }
    if(g.id==="2xko"){ if(B.x2[id]) out.push([g.id,"playable",B.x2[id]]); return; }
    if(g.id==="wildrift"){ if(B.wr[id]) out.push([g.id,"playable",B.wr[id]]); return; }
    if(g.id==="lor"){ if(LOR[id]&&LOR[id].length) out.push([g.id,"cards",LOR[id].length]); return; }
    if(g.id==="riftbound"){ if(RB[id]&&RB[id].length) out.push([g.id,"cards",RB[id].length]); return; }
    for(var r in g.roles){ if(g.roles[r].indexOf(id)>=0){ out.push([g.id,r,null]); return; } }
  });
  return out;
};
